/* apistatus.select_GROUP_SUMMARY_LIST */ SELECT as_grp.STATUS_GROUP_NM , as_grp.STATUS_GROUP_NO , ( AND (sub_as_if.STATUS_CODE = 'OK')) AS as_ok_count , () AS as_status_count FROM WHERE (1=1)
