/* apistatus.select_API_STATUS_CHECK_HIST_LIST */ SELECT as_chst.SEQ , a_sys.SYS_ID , a_sys.SYS_NM , a_spc.API_SPC_NO , a_spc.API_NM AS as_API_SPC_NM , a_def.API_NO , a_def.API_NM , TO_CHAR(as_chst.STATUS_CHECK_DT, 'YYYY-MM-DD HH24:MI:SS') AS STATUS_CHECK_DT , as_chst.STATUS_CODE , as_chst.STATUS_RES_MSEC FROM KOA_TB_API_STATUS_CHECK_HST as_chst INNER JOIN KOA_TB_API_DEF a_def ON (a_def.API_NO = as_chst.API_NO) INNER JOIN KOA_TB_API_SPC a_spc ON (a_spc.API_SPC_NO = a_def.API_SPC_NO)
AND (a_spc.AUT_ID IN
#{item}
)
INNER JOIN KOA_TB_API_SYSTEM a_sys ON (a_sys.SYS_ID = a_spc.SYS_ID)
AND (a_sys.SYS_ID IN
#{item}
)
WHERE (as_chst.API_NO = #{apiNo})
AND (EXTRACT(DAY FROM (NOW() - as_chst.STATUS_CHECK_DT)) <= #{statusCheckDtDays})
ORDER BY as_chst.SEQ DESC

